<div class="page-heading"><span class="eyebrow">MERCHANT WORKSPACE · FR-03 / FR-06 / FR-07</span><h1>Kelola pesanan</h1><p>Proses pesanan yang sudah dibayar, lalu tandai selesai setelah pemenuhan dilakukan.</p></div><?php if(!$orders): ?><div class="empty-state"><h3>Belum ada pesanan</h3><p>Pesanan baru dari konsumen akan muncul di halaman ini.</p></div><?php else: ?><div class="order-list"><?php foreach($orders as $o): ?><article class="panel order-card"><div class="order-card-head"><div><span class="eyebrow">ORDER #ORD-<?= (int)$o['order_id'] ?> · <?= e(date('d M Y H:i',strtotime($o['order_date']))) ?></span><h3><?= e($o['product_names']) ?></h3><span class="muted small">Konsumen: <?= e($o['consumer_name']) ?></span></div><span class="status status-<?= e($o['status']) ?>"><?= e(str_replace('_',' ',$o['status'])) ?></span></div><div class="order-card-detail"><span>Total: <strong><?= money($o['total_amount']) ?></strong></span><span>Pembayaran: <strong><?= e($o['payment_status']) ?></strong></span><span>Metode: <strong><?= e($o['fulfillment_method']) ?></strong></span><span>Tujuan: <strong><?= e($o['destination_address']?:'Ambil di toko') ?></strong></span></div><div class="order-card-actions"><?php if($o['status']==='dibayar'): ?><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="merchant_status"><input type="hidden" name="order_id" value="<?= (int)$o['order_id'] ?>"><input type="hidden" name="status_action" value="process"><button class="btn btn-primary btn-small">Proses pesanan</button></form><?php elseif($o['status']==='diproses'): ?><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="merchant_status"><input type="hidden" name="order_id" value="<?= (int)$o['order_id'] ?>"><input type="hidden" name="status_action" value="complete"><button class="btn btn-primary btn-small">Selesaikan pesanan</button></form><?php endif; ?><?php if(in_array($o['status'],['menunggu_pembayaran','dibayar'],true)): ?><form method="post" class="inline" data-confirm="Batalkan pesanan ini? Untuk pesanan yang sudah dibayar, pengembalian dana disimulasikan."><?= csrf_field() ?><input type="hidden" name="action" value="cancel_order"><input type="hidden" name="order_id" value="<?= (int)$o['order_id'] ?>"><input type="hidden" name="reason" value="Kendala stok atau operasional merchant"><button class="btn btn-outline btn-small">Batalkan pesanan</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?>
